public class WatchProtocolDecoderTest {

    @Test
    public void decode_WatchRequest_ReturnsTrue() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(Protocol.WATCH);
        assertTrue(decoder.getHasIndex());
    }

    @Test
    public void decode_WatchResponse_ReturnsFalse() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(Protocol.WATCH);
        assertFalse(decoder.getHasIndex());
    }

    @Test
    public void getManufacturer_WatchManufacturer_ReturnsCorrectValue() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(Protocol.WATCH);
        assertEquals("Watch", decoder.getManufacturer());
    }

    @Test
    public void decode_WatchRequest_WithLocation_ReturnsCorrectPosition() throws Exception {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(Protocol.WATCH);
        Position position = Position.builder()
                .latitude(37.7749)
                .longitude(-122.4194)
                .altitude(10)
                .heightAboveSeaLevel(5)
                .speed(25)
                .course(270)
                .accuracy(1)
                .timestamp(new Date())
                .build();
        Channel channel = Mockito.mock(Channel.class);
        SocketAddress remoteAddress = Mockito.mock(SocketAddress.class);
        Object msg = decoder.decode(channel, remoteAddress, position);
        assertNotNull(msg);
        assertTrue(BufferUtil.containsBytes((ByteBuf) msg, BufferUtil.encodePosition(37.7749, -122.4194, 10)));
    }

    @Test
    public void decode_WatchRequest_WithCellTower_ReturnsCorrectCellTower() throws Exception {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(Protocol.WATCH);
        CellTower cellTower = CellTower.builder()
                .cellId("123")
                .networkId("456")
                .mcc("777")
                .mnc("888")
                .lac("999")
                .cio("000")
                .timestamp(new Date())
                .build();
        Channel channel = Mockito.mock(Channel.class);
        SocketAddress remoteAddress = Mockito.mock(SocketAddress.class);
        Object msg = decoder.decode(channel, remoteAddress, cellTower);
        assertNotNull(msg);
        assertTrue(BufferUtil.containsBytes((ByteBuf) msg, BufferUtil.encodeCellTower("123", "456")));
    }

    @Test
    public void decode_WatchRequest_WithWifiAccessPoint_ReturnsCorrectWifiAccessPoint() throws Exception {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(Protocol.WATCH);
        WifiAccessPoint wifiAccessPoint = WifiAccessPoint.builder()
                .mac("111")
                .signalStrength(-50)
                .timestamp(new Date())
                .build();
        Channel channel = Mockito.mock(Channel.class);
        SocketAddress remoteAddress = Mockito.mock(SocketAddress.class);
        Object msg = decoder.decode(channel, remoteAddress, wifiAccessPoint);
        assertNotNull(msg);
        assertTrue(BufferUtil.containsBytes((ByteBuf) msg, BufferUtil.encodeWifiAccessPoint("111", -50)));
    }

    @Test
